                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.customerPrice
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.custtotal
                                            }
                                        </td>

                                    </tr>

                                )
                            )}

                            {balance > 0 && (

                                <tr>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        {balSNo}
                                    </td>

                                    <td
                                        style={{
                                            paddingLeft:
                                                "5px"
                                        }}
                                    >
                                        Balance
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                        colSpan={2}
                                    >
                                        ₹{balance}
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        ₹{balance}
                                    </td>

                                </tr>

                            )}

                        </tbody>

                    </table>

                    {/* AMOUNT */}

                    <table className="amtTable">

                        <tbody>

                            <tr>

                                <td
                                    style={{
                                        paddingLeft:
                                            "5px"
                                    }}
                                >

                                    <span
                                        style={{
                                            fontWeight:
                                                "bold"
                                        }}
                                    >
                                        Amount in words:
                                    </span>{" "}

                                    {numberToWords(
                                        grandTotal
                                    )}

                                </td>

                                <td
                                    style={{
                                        width: "90px",
                                        textAlign:
                                            "center",
                                        borderRight:
                                            "1px white solid",
                                        fontWeight:
                                            "bold"
                                    }}
                                >
                                    Grand Total
                                </td>

                                <td
                                    style={{
                                        width: "90px",
                                        textAlign:
                                            "center"
                                    }}
                                >
                                    {grandTotal}
                                </td>

                            </tr>

                        </tbody>

                    </table>

                    {/* FOOTER */}

                    <div className="footer">

                        <div className="terms">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                Terms & Condition
                                <sup>*</sup>
                            </span>

                            <br />

                            Payment must be paid within
                            15 days from the issue of bill.

                        </div>

                        <div className="signature">

                            <img
                                src={esign1}
                                style={{
                                    width: "70px",
                                    marginLeft: "350px"
                                }}
                                alt="signature"
                            />

                            <br />

                            Signature

                        </div>

                    </div>

                </div>

            </div>

        </div>
    );
}

export default MainPage;
